        long key = 0;
        for (int i = 0; i < k; i++) {
            key = (key << 2) | seq[start + i];
        }
        return key;
    }

    static Map<Long, long[]> buildCounts(int k) {
        HashMap<Long, long[]> map = new HashMap<>();
        int n = sequence.length - k + 1;
        for (int i = 0; i < n; i++) {
            long key = makeKey(sequence, i, k);
            long[] arr = map.get(key);
            if (arr == null) {
                arr = new long[1];
                map.put(key, arr);
            }
            arr[0]++;
        }
        return map;
    }

    static String keyToString(long key, int k) {
        char[] chars = new char[k];
        for (int i = k - 1; i >= 0; i--) {
            int code = (int) (key & 3);
            char c;
            switch (code) {
                case 0: c = 'A'; break;
                case 1: c = 'C'; break;
                case 2: c = 'G'; break;
                default: c = 'T';
            }
            chars[i] = c;
            key >>= 2;
        }
        return new String(chars);
    }

