        Map<Long, long[]> map = buildCounts(k);
        long total = 0;
        List<Map.Entry<Long, long[]>> entries = new ArrayList<>(map.entrySet());
        for (Map.Entry<Long, long[]> e : entries) total += e.getValue()[0];

        entries.sort((a, b) -> {
            long ca = a.getValue()[0], cb = b.getValue()[0];
            if (ca != cb) return Long.compare(cb, ca);
            return keyToString(a.getKey(), k).compareTo(keyToString(b.getKey(), k));
        });

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Long, long[]> e : entries) {
            double freq = e.getValue()[0] * 100.0 / total;
            sb.append(keyToString(e.getKey(), k));
            sb.append(' ');
            sb.append(String.format("%.3f", freq));
            sb.append('\n');
        }
        // remove trailing newline
        if (sb.length() > 0) sb.setLength(sb.length() - 1);
        return sb.toString();
    }

    static long count(String frag) {
        int k = frag.length();
        // build key for fragment
        byte[] fb = new byte[k];
        for (int i = 0; i < k; i++) {
            char c = frag.charAt(i);
            int code;
            switch (c) {
                case 'A': code = 0; break;
                case 'C': code = 1; break;
                case 'G': code = 2; break;
                default: code = 3;
            }
            fb[i] = (byte) code;
        }
        long targetKey = makeKey(fb, 0, k);

        Map<Long, long[]> map = buildCounts(k);
        long[] arr = map.get(targetKey);
        return arr == null ? 0 : arr[0];
