import java.util.concurrent.RecursiveAction;
import java.util.concurrent.ForkJoinPool;

public class spectralnorm {
    static double eval(int i, int j) {
        return 1.0 / (((long)(i + j) * (i + j + 1) / 2 + i + 1));
    }

    static void multiplyAv(double[] v, double[] out, int start, int end) {
        int n = v.length;
        for (int i = start; i < end; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) sum += eval(i, j) * v[j];
            out[i] = sum;
        }
    }

    static void multiplyAtv(double[] v, double[] out, int start, int end) {
        int n = v.length;
        for (int i = start; i < end; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) sum += eval(j, i) * v[j];
            out[i] = sum;
        }
    }

    static void multiplyAtAv(double[] v, double[] tmp, double[] out, ForkJoinPool pool) {
        int n = v.length;
        pool.invoke(new RecursiveAction() {
            protected void compute() { par(0, n, v, tmp, true); }
        });
        pool.invoke(new RecursiveAction() {
            protected void compute() { par(0, n, tmp, out, false); }
        });
    }

    static void par(int start, int end, double[] in, double[] outv, boolean av) {
        final int THRESHOLD = 128;
        if (end - start <= THRESHOLD) {
            if (av) multiplyAv(in, outv, start, end);
            else multiplyAtv(in, outv, start, end);
        } else {
            int mid = (start + end) >>> 1;
            RecursiveAction left = new RecursiveAction() {
                protected void compute() { par(start, mid, in, outv, av); }
            };
            RecursiveAction right = new RecursiveAction() {
                protected void compute() { par(mid, end, in, outv, av); }
            };
            invokeAll(left, right);
        }
    }

    static RecursiveAction invokeAll(RecursiveAction a, RecursiveAction b) {
        b.fork();
        a.compute();
        b.join();
        return null;
    }

    public static void main(String[] args) {
        int n = 4000;
        if (args.length > 0) n = Integer.parseInt(args[0]);

        double[] u = new double[n];
        double[] v = new double[n];
        double[] tmp = new double[n];
        for (int i = 0; i < n; i++) u[i] = 1.0;

        ForkJoinPool pool = new ForkJoinPool();

        for (int i = 0; i < 10; i++) {
            multiplyAtAv(u, tmp, v, pool);
            multiplyAtAv(v, tmp, u, pool);
        }

        double vBv = 0, vv = 0;
        for (int i = 0; i < n; i++) {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }

        pool.shutdown();

        System.out.printf("%.9f%n", Math.sqrt(vBv / vv));
    }
}
